import math
L=2.75;L2=2.6;A=1.05
X=0.0;Y=-0.42;PSI=math.radians(2.5)
mode='fwd';fd=0.0;woke=False;Yc=0.0;pts={};n=0
def cl(a,m):
    return max(-m,min(m,a))
def wr(a):
    while a>math.pi:a-=2*math.pi
    while a<-math.pi:a+=2*math.pi
    return a
def control(obs):
    global X,Y,PSI,mode,fd,woke,Yc,pts,n
    n+=1
    dt=obs['dt'];v=obs['motion']['v_mps'];d=math.radians(obs['steer_deg'])
    w=v*math.tan(d)/L
    pm=PSI+0.5*w*dt
    X+=v*math.cos(pm)*dt;Y+=v*math.sin(pm)*dt;PSI=wr(PSI+w*dt)
    h=obs['hitch_deg'];rig=obs['rig'];rx,ry=rig['trailer_rear']
    c=math.cos(PSI);s=math.sin(PSI)
    Xt=X+rx*c-ry*s;Yt=Y+rx*s+ry*c
    tht=wr(PSI-math.radians(h))
    views=obs.get('views') or {}
    near=False;Ly=[];Ry=[]
    ub=math.radians(180-h);ux=math.cos(ub);uy=math.sin(ub)
    for k,vw in views.items():
        ox,oy=vw['origin']
        for b,dd in vw.get('walls',[]):
            r=math.radians(b);px=ox+dd*math.cos(r);py=oy+dd*math.sin(r)
            wx=X+px*c-py*s;wy=Y+px*s+py*c
            if k!='periphery':
                key=(round(wx*2)/2,round(wy*2)/2);pts[key]=pts.get(key,0)+1
            if k=='camera':
                ex=px-rx;ey=py-ry;al=ex*ux+ey*uy;lat=-ex*uy+ey*ux
                if 0.3<al<4.0 and abs(lat)<1.2:near=True
            if Xt-3<wx<Xt+1 and k!='periphery':
                (Ly if wy>Yc else Ry).append(wy)
    if Ly and Ry and mode=='rev':
        ml=sum(Ly)/len(Ly);mr=sum(Ry)/len(Ry)
        if 3.0<ml-mr<5.5:
            Yc+=0.05*((ml+mr)/2-Yc);Yc=cl(Yc,1.0)
    if mode=='rev' and abs(h)>35:
        mode='fwd';fd=0.0
    if mode=='fwd':
        fd+=abs(v)*dt
        if (fd>2.0 and abs(h)<6) or fd>6.5:
            mode='rev'
        else:
            st=cl(-1.5*math.degrees(PSI)-8*(Y-Yc)-0.4*h,15)
            if n%10==0:print('F t%.1f h%.1f X%.2f Y%.2f psi%.1f'%(obs['t'],h,X,Y,math.degrees(PSI)))
            return (st,1.0,0)
    if mode=='stop':
        return (0.0,0.0,-23)
    if near and not woke:
        woke=True;mode='stop'
        print('POSE X%.2f Y%.2f psi%.1f Xt%.2f Yt%.2f tht%.1f Yc%.2f h%.1f'%(X,Y,math.degrees(PSI),Xt,Yt,math.degrees(tht),Yc,h))
        L_=sorted([k for k in pts if k[0]<Xt+3])
        print('MAP '+' '.join('%g,%g'%k for k in L_[:120]))
        wake('end wall close behind trailer')
        return (0.0,0.0,-23)
    e=Yt-Yc
    thd=cl(0.3*e,0.2)
    hd=cl(1.5*math.degrees(tht-thd),20)
    hr=math.radians(hd)
    ff=math.degrees(math.atan(L*math.sin(hr)/(L2+A*math.cos(hr))))
    st=cl(ff+2.5*(h-hd),34)
    sp=-0.8 if abs(h-hd)<10 else -0.5
    if n%10==0:print('R t%.1f h%.1f hd%.1f Xt%.2f Yt%.2f tht%.1f Yc%.2f'%(obs['t'],h,hd,Xt,Yt,math.degrees(tht),Yc))
    return (st,sp,-23)

