import math
mode='rev'
lat_c=0.0
n=0
def clamp(x,a):
    return max(-a,min(a,x))
def control(obs):
    global mode,lat_c,n
    n+=1
    phi=obs['hitch_deg']
    rig=obs['rig']
    r=rig['trailer_rear']
    psi=math.radians(rig['trailer_heading_deg'])
    bx,by=-math.cos(psi),-math.sin(psi)
    lx,ly=-math.sin(psi),math.cos(psi)
    views=obs.get('views') or {}
    lefts=[];rights=[]
    for k in ('direct','periphery'):
        v=views.get(k)
        if not v: continue
        ox,oy=v['origin']
        for b,d in v.get('walls',[]):
            px=ox+d*math.cos(math.radians(b))-r[0]
            py=oy+d*math.sin(math.radians(b))-r[1]
            al=px*bx+py*by
            la=px*lx+py*ly
            if 0.2<al<4.0 and abs(la)<3.0:
                if la>0: lefts.append(la)
                else: rights.append(la)
    est=None
    if lefts and rights:
        est=(min(lefts)+max(rights))/2
    elif lefts:
        est=min(lefts)-0.9
    elif rights:
        est=max(rights)+0.9
    tgt=obs.get('target') or {}
    talong=None
    if tgt.get('in_sight') and tgt.get('dist_m') is not None:
        e=rig['eye']
        px=e[0]+tgt['dist_m']*math.cos(math.radians(tgt['bearing_deg']))-r[0]
        py=e[1]+tgt['dist_m']*math.sin(math.radians(tgt['bearing_deg']))-r[1]
        talong=px*bx+py*by
        tla=px*lx+py*ly
        if talong>0.3:
            w=0.3 if talong>5 else 0.7
            est=tla if est is None else (1-w)*est+w*tla
    if est is not None:
        lat_c=0.6*lat_c+0.4*est
    else:
        lat_c*=0.97
    look=170
    if mode=='fwd':
        if abs(phi)<8:
            mode='rev'
        else:
            return (clamp(-1.5*phi,45),0.6,look)
    if abs(phi)>45:
        mode='fwd'
        return (clamp(-1.5*phi,45),0.6,look)
    e=math.degrees(math.atan2(lat_c,2.0))
    phid=clamp(1.2*e,22)
    steer=clamp(2.5*(phi-phid),45)
    sp=-0.5
    if talong is not None and talong<1.5: sp=-0.35
    if n%20==0: print(round(obs['t'],1),'phi',round(phi,1),'latc',round(lat_c,2),'phid',round(phid,1),'L',len(lefts),'R',len(rights),obs['progress']['covered'])
    return (steer,sp,look)

